head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > M > setValue]<br/>DatePicker 컴포넌트의 선택 날짜를 설정합니다.",
    "validation" : [
        "calendarValueType 속성값에 따른 포맷이 적용된 날짜 문자열을 value 파라미터로 설정하여야 합니다.",
        "String 타입의 value(필수) 파라미터로 설정할 날짜를 문자열로 설정합니다.",
        "calendarValueType='yearMonth' 인 경우 'yyyyMM' 포맷의 6자리 문자열을 설정합니다.",
        "calendarValueType='yearMonthDate' 인 경우 'yyyyMMdd' 포맷의 8자리 문자열을 설정합니다.",
        "calendarValueType='yearMonthDateTime' 인 경우 'yyyyMMddHHmm' 포맷의 12자리 문자열을 설정합니다.",
        "calendarValueType='hourMinute' 인 경우 'HHmm' 포맷의 4자리 문자열을 설정합니다.",
        "파라미터가 null, undefined 이면 메소드가 실행되지 않습니다.",
        "값이 변경되면 onchange 이벤트가 발생합니다.",
        "시간값은 24시간제로 설정합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let calendarValueType = con_calendarValueType.getText();

    let properties = {
        calendarValueType : calendarValueType
    };

    let cList = $c.gcm.createCList(properties);

    // onchange 핸들러 등록 (setValue 호출 시 발생 여부 확인용) - 공통 모듈 사용
    let eList = $c.gcm.createEList(["onchange"]);

    await $c.gcm.createBasicDatePicker(cList, eList);
};



// onchange 핸들러 - setValue 호출 시 발생 여부 확인
scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생]");
};



// setValue 호출 (선택된 par_value 값 / null / undefined 모두 한 버튼으로 처리)
scwin.btn_setValue_onclick = function (e) {
    let selected = par_value.getText();
    let valueType = target1.options.calendarValueType || 'yearMonthDate';

    // selectbox 라벨 'null' / 'undefined' 는 실제 null / undefined 로 변환
    let inputValue;
    if (selected === "null") {
        inputValue = null;
    } else if (selected === "undefined") {
        inputValue = undefined;
    } else {
        inputValue = selected;
    }

    let beforeValue = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[setValue 입력값] " + (inputValue === null ? "null" : (inputValue === undefined ? "undefined" : "'" + inputValue + "'")));

    target1.setValue(inputValue);

    let rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[getValue() 결과] '" + rtn + "'");

    // null/undefined 호출 시 메소드 미실행 → 값 변화 없음 확인
    if (inputValue === null || inputValue === undefined) {
        wf_body_bottom.getObj("scwin").setReturnValue("[값 변화 없음 여부] " + (beforeValue === rtn));
    }

    // 24시간제 검증: yearMonthDateTime / hourMinute 인 경우 입력한 14시가 '14' 로 포함되는지 확인
    if ((valueType === 'yearMonthDateTime' || valueType === 'hourMinute') && inputValue !== null && inputValue !== undefined) {
        let hourPart = (valueType === 'yearMonthDateTime') ? rtn.substring(8, 10) : rtn.substring(0, 2);
        wf_body_bottom.getObj("scwin").setReturnValue("[24시간제 시(HH) 부분] '" + hourPart + "' (14 포함 여부: " + (hourPart === '14') + ")");
    }
};
